from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route("/send_gift", methods=["POST"])
def send_gift():
    recipient = request.form["recipient"]
    gift = request.form["gift"]
    message = f"<p>On behalf of the world we want to give you: {gift}<br>{recipient}</p>"
    signed_msg = message + "ƿ"

    return render_template_string(signed_msg)

if __name__ == "__main__":
    app.run()
